package com.codeforge.ide;

import android.app.*;import android.os.*;import android.graphics.Color;import android.view.*;import android.widget.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.*;

public class MainActivity extends Activity {
  LinearLayout root, tree, tabs; EditText editor, prompt; TextView status; File project, current; String apiKey="";
  int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);} TextView tv(String s){TextView t=new TextView(this);t.setText(s);t.setTextColor(Color.LTGRAY);t.setPadding(dp(10),dp(8),dp(10),dp(8));return t;}
  public void onCreate(Bundle b){super.onCreate(b); project=new File(getFilesDir(),"DemoProject"); if(!project.exists())project.mkdirs(); seed(); buildUi();}
  void seed(){try{File f=new File(project,"MainActivity.java");if(!f.exists())write(f,"// Start coding with Gemini\npublic class MainActivity {\n    // Your code here\n}\n");File r=new File(project,"README.md");if(!r.exists())write(r,"# DemoProject\n\nBuilt with CodeForge IDE.\n");}catch(Exception e){}}
  void buildUi(){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.rgb(30,31,34));
    LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.addView(tv("  CODEFORGE IDE  "),new LinearLayout.LayoutParams(dp(150),-1));
    String[] actions={"New","Save","Build APK","Gemini"}; for(String a:actions){Button x=new Button(this);x.setText(a);bar.addView(x,new LinearLayout.LayoutParams(-2,-1)); if(a.equals("New"))x.setOnClickListener(v->newFile()); if(a.equals("Save"))x.setOnClickListener(v->save()); if(a.equals("Build APK"))x.setOnClickListener(v->buildInfo()); if(a.equals("Gemini"))x.setOnClickListener(v->askGemini());} root.addView(bar,new LinearLayout.LayoutParams(-1,dp(54)));
    LinearLayout body=new LinearLayout(this);tree=new LinearLayout(this);tree.setOrientation(LinearLayout.VERTICAL);tree.setPadding(dp(4),dp(8),dp(4),0);refreshTree(); ScrollView sv=new ScrollView(this);sv.addView(tree);body.addView(sv,new LinearLayout.LayoutParams(dp(210),-1));
    LinearLayout center=new LinearLayout(this);center.setOrientation(LinearLayout.VERTICAL);tabs=new LinearLayout(this);center.addView(tabs,new LinearLayout.LayoutParams(-1,dp(42)));editor=new EditText(this);editor.setGravity(Gravity.TOP|Gravity.START);editor.setTextColor(Color.WHITE);editor.setTextSize(14);editor.setBackgroundColor(Color.rgb(37,38,43));editor.setPadding(dp(14),dp(10),dp(10),dp(10));center.addView(editor,new LinearLayout.LayoutParams(-1,0,1));status=tv("Ready • project: DemoProject");center.addView(status);body.addView(center,new LinearLayout.LayoutParams(0,-1,1)); root.addView(body,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);open(new File(project,"MainActivity.java")); }
  void refreshTree(){tree.removeAllViews();list(project,"");}
  void list(File dir,String ind){File[] fs=dir.listFiles();if(fs==null)return;for(File f:fs){if(f.isDirectory())continue;TextView x=tv(ind+"▸ "+f.getName());tree.addView(x);x.setOnClickListener(v->open(f));}}
  void open(File f){current=f;try{editor.setText(read(f));tabs.removeAllViews();tabs.addView(tv("  "+f.getName()+"  "));status.setText("Editing "+f.getAbsolutePath());}catch(Exception e){status.setText(e.toString());}}
  void save(){try{write(current,editor.getText().toString());status.setText("Saved "+current.getName());}catch(Exception e){status.setText(e.toString());}}
  void newFile(){final EditText n=new EditText(this);n.setHint("File name, e.g. Feature.kt");new AlertDialog.Builder(this).setTitle("New file").setView(n).setPositiveButton("Create",(d,w)->{try{File f=new File(project,n.getText().toString());write(f,"// New file\n");refreshTree();open(f);}catch(Exception e){}}).setNegativeButton("Cancel",null).show();}
  void buildInfo(){new AlertDialog.Builder(this).setTitle("APK build").setMessage("This project is built by GitHub Actions. Download the debug APK from the workflow artifact.").setPositiveButton("OK",null).show();}
  void askGemini(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);prompt=new EditText(this);prompt.setHint("Ask Gemini to explain, edit, or generate code");EditText key=new EditText(this);key.setHint("Gemini API key (stored only on this device)");key.setInputType(129);l.addView(prompt);l.addView(key);new AlertDialog.Builder(this).setTitle("Gemini Assistant").setView(l).setPositiveButton("Send",(d,w)->{apiKey=key.getText().toString();callGemini(prompt.getText().toString());}).setNegativeButton("Cancel",null).show();}
  void callGemini(String q){status.setText("Gemini is thinking…");Executors.newSingleThreadExecutor().execute(()->{try{String body="{\"contents\":[{\"parts\":[{\"text\":"+json(q+"\nCurrent file:\n"+editor.getText())+"}]}]}";URL u=new URL("https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key="+apiKey);HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setRequestMethod("POST");c.setRequestProperty("Content-Type","application/json");c.setDoOutput(true);c.getOutputStream().write(body.getBytes(StandardCharsets.UTF_8));String r=read(new BufferedReader(new InputStreamReader(c.getInputStream())));runOnUiThread(()->new AlertDialog.Builder(this).setTitle("Gemini response").setMessage(r).setPositiveButton("Close",null).show());}catch(Exception e){runOnUiThread(()->status.setText("Gemini error: "+e.getMessage()));}});}
  String json(String s){return "\""+s.replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n")+"\"";} String read(File f)throws Exception{return new String(java.nio.file.Files.readAllBytes(f.toPath()),StandardCharsets.UTF_8);} String read(BufferedReader b)throws Exception{StringBuilder s=new StringBuilder();String x;while((x=b.readLine())!=null)s.append(x);return s.toString();}void write(File f,String s)throws Exception{java.nio.file.Files.write(f.toPath(),s.getBytes(StandardCharsets.UTF_8));}
}